class SplunkbaseException(Exception):
    def __init__(self, msg):
        Exception.__init__(self, msg)

NODEFAULT = object()
class XMLParseError(Exception): pass

class FlaggedElement(object):
    def __init__(self, value):
        self.value = value

class DisableElement(FlaggedElement):
    """Allow for processValue* statements to force disable an element on a manager page"""
    pass

class EnableElement(FlaggedElement):
    """Allow for processValue* statements to force enable an element on a manager page"""
    pass

def pass_label_to_subelement(element_dict, subelement_dict):
    """
    Passes `label` attrib to unpacked subelement
    if it is a template and has `inheritLabel` attribute.
    """
    is_template = subelement_dict.get('elementName') == 'template'
    is_inherit_flag_set = subelement_dict.get('inheritLabel')
    parent_has_label = 'label' in element_dict
    if is_template and is_inherit_flag_set and parent_has_label:
        subelement_dict['label'] = element_dict['label']

def filter_out_entities_by_names(entities, stanzas_to_remove):
    """
    Removes entities from the `entities` dict if the key ends with one of strings
    from the `stanzas_to_remove` list.
    """
    if not isinstance(entities, dict):
        return entities
    return {key: value for key, value in entities.items() if not any(key.endswith(f'/{stanza}') for stanza in stanzas_to_remove)}

def _unpackOnChange(onChange):
    onChange_dict = {}
    for k in onChange:
        if k.tag == 'group_set':
            onChange_dict['_groupset'] = [group.attrib['name'] for group in k]
        elif k.tag == 'value_map':
            onChange_dict['value_map'] = dict([(key.attrib['name'], key.text if key.text else '') for key in k])
        elif k.tag == 'chained_action':
            onChange_dict['_chained_action'] = _unpackOnChange(k)
        else:
            onChange_dict[k.attrib['name']] = k.text

    return onChange_dict


def _unpackOpt(opt):
    type = opt.attrib.get('type')
    if type:
        if type == 'dict':
            return_dict = {}
            for o in opt:
                return_dict[o.attrib['name']] = _unpackOpt(o)
            return return_dict
        elif type  == 'list':
            return_list = []
            for item in opt:
                return_list.append(_unpackOpt(item))
            return return_list

    return opt.text

def _unpackElement(element):
    element_dict = {}
    if 'name' in element.attrib:
        element_dict['elementName'] = element.attrib['name']

    for attr in ('type', 'label', 'class', 'maxlength'):
        if not attr in element.attrib:
            continue

        element_dict[attr] = element.attrib[attr]

    onChanges = element.findall('onChange')
    if len(onChanges) == 1:
        element_dict['onChange'] = _unpackOnChange(onChanges[0])
    elif len(onChanges) > 1:
        element_dict['onChange'] = [_unpackOnChange(onChange) for onChange in onChanges]


    for o_type in ('options', 'extraOptions'):
        o_node = element.find(o_type)

        if not o_node:
            continue

        element_dict[o_type] = [{'value': opt.attrib['value'], 'label': _(opt.attrib['label'])} for opt in o_node]

    views = element.findall('view')
    if views:
        element_dict['showInView'] = [view.attrib['name'] for view in views]

    opts = element.findall('key')
    for opt in opts:
        element_dict[opt.attrib['name']] = _unpackOpt(opt)

    elements = element.find('elements')
    if elements:
        element_dict['elements'] = [_unpackElement(e) for e in elements]

    # type=repeatable uses this
    subelement = element.find('element')
    if subelement:
        subelement_dict = _unpackElement(subelement)
        pass_label_to_subelement(element_dict, subelement_dict)
        element_dict['element'] = subelement_dict

    return element_dict

def _unpack(root_str, search=None):

    if not root_str: return

    parser = et.XMLParser(remove_blank_text=True, remove_comments=True)
    root = et.fromstring(root_str, parser=parser)

    if root.tag != 'endpoint':
        return (None, None)

    if search and root.attrib['name'] != search:
        return (None, None)

    contents = {}

    contents['redirect'] = normalizeBoolean(root.attrib['redirect']) if 'redirect' in root.attrib else True
    if 'hideEnabledColumn' in root.attrib:
        # logger.debug("should hide enabled column.")
        contents['hideEnabledColumn'] = normalizeBoolean(root.attrib['hideEnabledColumn'])
    if 'hidePermissionsColumn' in root.attrib:
        # logger.debug("should hide permissions column.")
        contents['hidePermissionsColumn'] = normalizeBoolean(root.attrib['hidePermissionsColumn'])
    if 'hideActionsColumn' in root.attrib:
        # logger.debug("should hide actions column.")
        contents['hideActionsColumn'] = normalizeBoolean(root.attrib['hideActionsColumn'])
    if 'displayNameField' in root.attrib:
        contents['displayNameField'] = root.attrib['displayNameField']
    if 'packageName' in root.attrib:
        contents['packageName'] = root.attrib['packageName']

    contents['header'] = root.findtext('header')
    contents['introText'] = root.findtext('introText')

    breadcrumb = root.find('breadcrumb')
    if breadcrumb:
        breadcrumb_parent_node = breadcrumb.find('parent')
        if breadcrumb_parent_node is not None:
            contents['breadcrumb_parent'] = breadcrumb_parent_node.text
            contents['breadcrumb_hide_current'] = normalizeBoolean(breadcrumb_parent_node.attrib['hidecurrent']) if 'hidecurrent' in breadcrumb_parent_node.attrib else False
        breadcrumb_noentity = breadcrumb.findtext('noentity')
        contents['breadcrumb_noentity'] = normalizeBoolean(breadcrumb_noentity) if breadcrumb_noentity else False
        contents['breadcrumb_name'] = breadcrumb.findtext('name')
        contents['breadcrumb_entityname'] = breadcrumb.findtext('entityname')

    if 'showAppContext' in root.attrib:
        contents['showAppContext'] = root.attrib['showAppContext']

    if 'applyListFilter' in root.attrib:
        contents['applyListFilter'] = root.attrib['applyListFilter']

    menu = root.find('menu')
    if menu:
        menu_dict = {}
        if 'name' in menu.attrib:
            menu_dict['name'] = menu.attrib['name']
        for menu_opt in ('label', 'url', 'description', 'id'):
            menu_opt_node = menu.find(menu_opt)
            if menu_opt_node != None:
                menu_dict[menu_opt] = menu_opt_node.text

        order_node = menu.find('order')
        menu_dict['order'] = 0
        if order_node != None:
            try:
                menu_dict['order'] = int(order_node.text)
            except:
                pass

        link_nodes = menu.findall('link')
        for link in link_nodes:
            link_dict = {}
            for opt in link.findall('key'):
                link_dict[opt.attrib['name']] = _unpackOpt(opt)
            menu_dict.setdefault('links', []).append(link_dict)

        contents['menu'] = menu_dict


    elements = root.find('elements')

    if elements:
        contents['elements'] = [_unpackElement(element) for element in elements]

    if 'template' in root.attrib:
        if check_feature_flags_for_pages_migrated_directly_from_xml_to_react(
                root.attrib['name']):
            contents['template'] = root.attrib['template']
            contents['displayV2Page'] = True
        elif root.attrib['name'] in LEGACY_TEMPLATE:
            contents['template'] = LEGACY_TEMPLATE[
                root.attrib['name']]
            contents['displayV2Page'] = False

    return (root.attrib['name'], contents)


def _extractPathFromURI(uri, preserve_query=False):
    """Parses the URI, strips the scheme and netloc, and returns a sanitized path."""
    if uri is None or not isinstance(uri, str) or not uri.strip():
        return None

    parsed_uri = urllib_parse.urlsplit(uri)

    sanitized_path = parsed_uri.path
    # Reject paths that looks suspicious to prevent SSRF risks. Validate against
    # a decoded copy so an encoded traversal or scheme segment (e.g. %2e%2e)
    # cannot slide past these checks; the original, still-encoded path is what
    # gets forwarded below.
    decoded_path = sanitized_path
    # Bound decoding to limit work on attacker-controlled paths.
    for _ in range(10):
        next_decoded_path = urllib_parse.unquote(decoded_path)
        if next_decoded_path == decoded_path:
            break
        decoded_path = next_decoded_path
    else:
        return None
    if any(i in decoded_path.lower() for i in ("http:", "https:")):
        return None

    if any(i == ".." for i in decoded_path.split('/')):
        return None

    sanitized_path = re.sub(r'/{2,}', '/', sanitized_path)

    # Remove scheme, netloc, and fragments. Queries are preserved only for
    # endpoint-owned arguments such as remote-monitor app_name; forwarding the
    # full query would let a crafted uri smuggle unrelated request-target/
    # auth-context parameters through this exception.
    sanitized_query = ''
    if preserve_query:
        query_pairs = urllib_parse.parse_qsl(parsed_uri.query, keep_blank_values=True)
        sanitized_query = urllib_parse.urlencode(
            [(key, value) for key, value in query_pairs if key == 'app_name']
        )
    sanitized_uri = ('', '', sanitized_path, sanitized_query, '')

    return urllib_parse.urlunsplit(sanitized_uri)

def _getAllowedListEntityApiArgs(kwargs, existing_args):
    api_args = {}
    for key, value in kwargs.items():
        if not key.lower().startswith('api.'):
            continue

        arg_name = key[4:]
        canonical_arg_name = LIST_ENTITIES_API_ARG_ALLOWLIST.get(arg_name.lower())
        if canonical_arg_name is None or canonical_arg_name in existing_args:
            continue

        api_args[canonical_arg_name] = value

    return api_args

def _shouldPreserveEndpointUriQuery(endpoint_path):
    return endpoint_path.startswith('deployment/server/setup/data/inputs/remote_monitor')

def _isSensitiveSaveEntityLogField(field_name):
    normalized = str(field_name).lower().replace('-', '_')
    return any(field_part in normalized for field_part in SENSITIVE_SAVE_ENTITY_LOG_FIELD_PARTS)

def _redactSaveEntityArgsForLog(args):
    if not hasattr(args, 'items'):
        return args

    redactedArgs = {}
    for key, value in args.items():
        if _isSensitiveSaveEntityLogField(key):
            redactedArgs[key] = REDACTED_SAVE_ENTITY_LOG_VALUE
        else:
            redactedArgs[key] = value

    return redactedArgs

def _cleanseCRLF(uri):
    '''Prevent splunkd request chaining SPL-73544 '''
    import splunk.util
    if uri == None:
        return uri
    elif isinstance(uri, splunk.util.string_type):
        try:
            cleanUri = uri.splitlines()[0]
        except:
            cleanUri = uri
        return cleanUri

def _unpackManagerXmlElementFromStr(xml_str):
    """
    given an XML string that represents a manager xml <element> block, unpacks
    it into a python dict
    """
    parser = et.XMLParser(remove_blank_text=True, remove_comments=True)
    element = et.fromstring(xml_str, parser=parser)

    contents = None
    if element is not None:
        contents = _unpackElement(element)
    return contents


