def _is_DMCDisabled():
    """
    Checks if DMC is enabled
    :return bool:
    """
    # return cached value if not none
    if DMC_SETTINGS['status'] is not None:
        return DMC_SETTINGS['status']

    isDMCDisabled = True
    try:
        dmc_settings = en.getEntity(DMC_SETTINGS['url'], 'settings')
        isDMCDisabled = normalizeBoolean(dmc_settings['disabled'])
    except splunk.RESTException as e:
        # SPL-158060: This exception should not be logged as error because we know this
        # is part of normal workflow (DMC url not configured).
        logger.info('Failed to fetch DMC settings to verify status')
    except KeyError as e:  # handle key exception when fetching disabled state.
        logger.error('Failed to fetch DMC disabled status')
        logger.exception(e)
    except ValueError as e:  # handle normalize boolean exception.
        logger.error('Failed to parse disabled status')
        logger.exception(e)

    DMC_SETTINGS['status'] = isDMCDisabled
    return isDMCDisabled


def _is_redirect_safe(url):
    """ See if a string returns a network path location
    """

    # Catch things like https:// http:// file://
    o = urllib_parse.urlparse(url)
    if o.scheme:
        return False

    slash_prefix_cnt = 0

    for c in url:
        if c in ('/', '\\'):
            slash_prefix_cnt += 1
            if slash_prefix_cnt >= 2:
                return False
        elif c in ('\x09', '\x0b'):
            continue
        else:
            return True


def _sanitizeEvalInputs(evalStr):
    """
    SPL-235737: Sanitize eval str to prevent RCE vulnerability using python dunder methods
    """
    # Explicitly allow only known-safe dunder names required by legacy manager XML.
    allowed_dunder_names = {'__setitem__'}
    allowed_dunder_call_roots = {
        '__setitem__': {'form_defaults'},
    }
    blocked_names = {'exec', 'compile', 'open', 'eval', 'input', '__import__'}

    def _is_allowed_dunder_usage(expression, dunder_name):
        """Allow specific dunder names only for known-safe call shapes."""
        try:
            tree = ast.parse(expression, mode='eval')
        except SyntaxError:
            return False

        allowed_roots = allowed_dunder_call_roots.get(dunder_name, set())
        if not allowed_roots:
            return False

        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            if not isinstance(func, ast.Attribute):
                continue
            if func.attr != dunder_name:
                continue
            if isinstance(func.value, ast.Name) and func.value.id in allowed_roots:
                return True

        return False

    stripped_eval = evalStr.strip()
    c = compile(stripped_eval, '<string>', 'eval')
    pending = [c]
    while pending:
        code = pending.pop()
        names = list(code.co_names)
        strings = [v for v in code.co_consts if isinstance(v, str)]

        for value in names:
            if value in blocked_names:
                raise NameError("Use of {} is not allowed".format(value))

        for value in names + strings:
            if isinstance(value, str) and '__' in value and (
                value not in allowed_dunder_names or not _is_allowed_dunder_usage(stripped_eval, value)
            ):
                raise NameError("Use of {} is not allowed".format(value))
        pending.extend(v for v in code.co_consts if hasattr(v, 'co_names'))
    return c

def _enhanceDataInputsWithServerClasses(endpoint_path, entities, ns, sessionKey):
    if endpoint_path == 'deployment/server/setup/data/inputs/remote_monitor' and len(entities.keys()) > 0:
        app_args = {'namespace': ns, 'owner':'-', 'search':'serverclasses="*"', 'count':-1, 'offset':0, 'sessionKey':sessionKey}
        apps = en.getEntities('deployment/server/applications', **app_args)
        for item in entities.values():
            if 'eai:appName' in item and item['eai:appName'] in apps and 'serverclasses' in apps[item['eai:appName']]:
                item['serverClasses'] = apps[item['eai:appName']]['serverclasses']
            else:
                item['serverClasses'] = []
    return entities


