"""
Checks if route is protected by feature-flag (FEATURE_FLAGGED_ROUTES)
If the route is protected by feature-flag then it is enabled only if FF is True

@type  string
@param endpoint_path: A route to check

@rtype: Boolean
@return: True for not protected routes and routes with feature flag is True.
"""
def _check_is_route_enabled(endpoint_path):
    if endpoint_path in FEATURE_FLAGGED_ROUTES:
        feature = FEATURE_FLAGGED_ROUTES[endpoint_path]
        feature_name = feature.get('feature_name', None)
        flag_name = feature.get('flag_name', None)
        if not feature_name:
            raise NameError(
                f'FEATURE_FLAGGED_ROUTES has no feature_name prop for the {endpoint_path}'
            )
        if not flag_name:
            raise NameError(
                f'FEATURE_FLAGGED_ROUTES has flag_name prop for the {endpoint_path}'
            )
        return is_feature_enabled(feature_name, flag_name)
    return True

def manager_to_view_redirect(namespace, endpoint_path):
    """
    Redirects legacy manager pages from MANAGER_REDIRECTS list 
    will redirect /manage/{namespace}/{endpoint_path}
    to /app/{namespace}/{endpoint_path}

    Args:
        namespace (str): The current namespace (app).
        endpoint_path (str): The current endpoint path.

    Returns:
        str or None: Redirect URL if matched, else None.
    """

    redirect = MANAGER_REDIRECTS.get(endpoint_path, None)

    if redirect is None:
        return None

    if 'global' in redirect and redirect.get('global'):
        return f"/app/{namespace}/{endpoint_path}"

    if namespace in redirect and redirect.get(namespace):
        return f"/app/{namespace}/{endpoint_path}"

    return None

def check_apps_local_capabilities(endpoint_base, can_create_entity, can_edit_collection_item=None, entity_name=None):
    """
    Checks capabilities for apps/local endpoint access.

    References: VULN-19218, VULN-29963, SPL-289861

    Args:
        endpoint_base (str): The base endpoint being accessed.
        can_create_entity (Callable[[str], bool]): Function to check create capability.
        can_edit_collection_item (Callable[[str, str], bool], optional): Function to check edit 
            capability on collection items. Accepts (path, entity_name).
        entity_name (str, optional): The specific entity being edited.

    Returns:
        dict or None: Error response if unauthorized, otherwise None.
    """
    if endpoint_base != "apps/local":
        return None
    if can_create_entity('apps/local'):
        return None
    if can_edit_collection_item and can_edit_collection_item('apps/local', entity_name):
        return None
    return {
        'status': 'ERROR',
        'msg': str(splunk.AuthorizationFailed()),
    }

def can_edit_login_page_settings(fetch_capabilities=None):
    if fetch_capabilities is None:
        fetch_capabilities = fetch_current_user_capabilities
    try:
        capabilities = fetch_capabilities() or []
    except Exception:
        return False
    return LOGIN_PAGE_SETTINGS_CAPABILITY in capabilities

def _validateMaxLength(element, key, value):
    """
    Validates field value for the max length

    References:
        element (dict): Ui_helper for the form element holdinig input rules
        key (str): data element name.
        value (str): value to check 
    Returns:
        dict or False: A JSON response if value is iunvalid, otherwise False.
    """
    maxlength = None
    # default input type in templates is textfield, otherwise element has type
    eltype = element.get('type', 'textfield') 
    if 'maxlength' in element:
        maxlength = element.get('maxlength')
    if maxlength is not None and len(value) > int(maxlength):
        return {
                'status': 'FIELD_ERRORS',
                'fields': { 
                    key: f"Max length of {key} field is {maxlength} chars." 
                },
            }

