# Dashboard attribute validation functions
# Validates and sanitizes script and stylesheet file references in dashboard XML

def validate_dashboard_file_attribute(file_value: str, allowed_extension: str) -> Result[str, str]:
    """
    Validate script or stylesheet attribute for dashboard XML.
    
    Rules:
    1. Comma-separated list of custom files with specified extension
    2. Files must be in appserver/static directory or subdirectories
    3. Can reference files from other apps using "appName:fileName.ext" format
    4. No path traversal allowed
    5. Only files with the specified extension allowed
    
    Args:
        file_value (str): The attribute value to validate
        allowed_extension (str): Expected file extension ('js' or 'css')
        
    Returns:
        Result[Optional[str], str]: Success with sanitized value or Failure with error message
    """
    if not file_value or not isinstance(file_value, str):
        return Success("")  # Empty is valid
    
    # Pre-compiled regex patterns
    DANGEROUS_PATTERNS = re.compile(r'%2e%2e|&#x0A;|javascript:|data:|vbscript:', re.IGNORECASE)

    # Reject if contains dangerous patterns
    if DANGEROUS_PATTERNS.search(file_value):
        return Failure("Attribute contains dangerous patterns")
    
    # Split by comma and validate each file
    files = [f.strip() for f in file_value.split(',') if f.strip()] 

    if not files:
        return Success("")
    
    # Validate each file  
    validated_files = []
    for file_path in files:
        # Check for path traversal attempts
        try:
            normalized = PurePosixPath(file_path)
            if normalized.is_absolute() or '..' in normalized.parts:
                return Failure(f"Path traversal detected in: {file_path}")
        except ValueError:
            return Failure(f"Invalid file path: {file_path}")
        
        # Validate format - only accept the specified extension
        if ':' in file_path:
            # App reference format: appName:fileName.ext
            pattern = rf'^[a-zA-Z0-9_-]+:[^/\\:*?"<>|]{{1,100}}\.{allowed_extension}$'
            if not re.match(pattern, file_path, re.IGNORECASE):
                return Failure(f"Invalid app reference (expected .{allowed_extension}): {file_path}")
        else:
            # Regular file with specified extension
            pattern = rf'^[^\\:*?"<>|/]{{1,100}}\.{allowed_extension}$'
            if not re.match(pattern, file_path, re.IGNORECASE):
                return Failure(f"Invalid file (expected .{allowed_extension}): {file_path}")
        
        validated_files.append(file_path)
    
    # Return sanitized value (comma-separated, no extra spaces)
    sanitized_value = ','.join(validated_files)
    return Success(sanitized_value)

def validate_and_sanitize_dashboard_file_attribute(
    file_value: Optional[str], 
    allowed_extension: str
) -> Result[Optional[str], str]:
    """
    Enhanced validation with sanitization for dashboard file attributes.
    
    Args:
        file_value: The attribute value to validate and sanitize
        allowed_extension: Expected file extension ('js' or 'css')
        
    Returns:
        Result[Optional[str], str]: Success with sanitized value or Failure with error message
    """
    
    if file_value is None:
        return Success(None)

    decoded_value = urllib_parse.unquote(file_value)
    decoded_value = html.unescape(decoded_value)
    file_value_stripped = re.sub(r'\s+', '', decoded_value)
    
    # Validate the attribute value
    result = validate_dashboard_file_attribute(file_value_stripped, allowed_extension)
    
    if not isinstance(result, Success):
        error_msg = result.failure()
        logger.warning(f"Invalid {allowed_extension} attribute: {error_msg}")
        return Failure(error_msg)
    
    sanitized_value = result.unwrap()
    logger.info(f"Validated and sanitized {allowed_extension} file: {sanitized_value}")
    return Success(sanitized_value)  


# LOOKUP TABLE FILES
class LookupTableFile(SplunkAppObjModel):
    resource = '/data/lookup-table-files'
    path = Field(api_name='eai:data')


class LookupType(Enum):
    CSV = 'csv'
    KV = 'kv'
    KMZ = 'kmz'
    KML = 'kml'
    BACKUP_FILE = 'backup_details_for_lookups'


class LookupConstants:
    MAXIMUM_EDITABLE_SIZE = 10 * 1024 * 1024
    NUMBER_VALIDATION_REGEX = '^[0-9]+\.[0-9]+$'
    DEFAULT_APP = 'system'
    OPTION_NOBODY = 'nobody'


class PermissionDeniedException(Exception):
    pass


class NoOwnerException(Exception):
    pass


class LookupAlreadyExistsException(Exception):
    pass


class LookupNameInvalidException(Exception):
    pass


class LookupFileTooBigException(Exception):
    def __init__(self, file_size):
        Exception.__init__(self, file_size)
        self.file_size = file_size


class LookupHandler(PersistentServerConnectionApplication):
    """
    Persistent REST handler for lookup editor endpoints.

    The handler parses the incoming request payload, builds a Request object,
    and dispatches the call to a method whose name is derived from the HTTP
    method and request path.

    Routed methods receive the parsed request object plus any query or form
    parameters as keyword arguments.
    """

    def __init__(self, command_line=None, command_arg=None, logger=None):
        if logger is None:
            logger = logging.getLogger('splunk.appserver.controllers.admin')
        self.logger = logger
        PersistentServerConnectionApplication.__init__(self)

    # Utils
    @staticmethod
    def _get_function_signature(method, path):
        if len(path) > 0:
            return method + '_' + re.sub(r'[^a-zA-Z0-9_]', '_', path).lower()
        else:
            return method

    @staticmethod
    def _render_json(data, response_code=200):
        return {'payload': json.dumps(data), 'status': response_code, 'headers': {'Content-Type': 'application/json'}}

    @staticmethod
    def _render_error_json(message, response_code=500):
        data = {'success' : False, 'message' : message}

        return {'payload': json.dumps(data), 'status': response_code}

    @staticmethod
    def _get_forms_args_as_dict(form_args):
        result = {}

        for arg in form_args:
            name, value = arg[0], arg[1]
            result[name] = value

        return result
    
    @staticmethod
    def _convert_to_dict(query):
        parameters = {}

        for key, value in query:
            if key in parameters and not isinstance(parameters[key], list):
                parameters[key] = [parameters[key], value]
            elif key in parameters:
                parameters[key].append(value)
            else:
                parameters[key] = value

        return parameters
    
    @staticmethod
    def _convert_array_to_csv(array):
        output = io.StringIO()
        writer = csv.writer(output)

        for row in array:
            writer.writerow(row)

        return output.getvalue()
    
    @staticmethod
    def _is_empty(row):
        for entry in row:
            if entry is not None and len(entry.strip()) > 0:
                return False

        return True

    def _parse_request_string(self, request_string):
        params = json.loads(request_string)

        params['method'] = params['method'].lower()
        params['form_parameters'] = self._convert_to_dict(params.get('form', []))
        params['query_parameters'] = self._convert_to_dict(params.get('query', []))

        return params
    
    @staticmethod
    def _format_size(bytes, decimals = 2):
        bytes_int = int(bytes)

        if bytes_int <= 0:
            return '0 Bytes'

        k = 1024
        dm = 0 if decimals < 0 else decimals
        sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB']
        i = int(math.floor(math.log(bytes_int, k)))
        p = math.pow(k, i)
        s = round(bytes_int / p, dm)

        return '%s %s' % (s, sizes[i])

    @staticmethod
    def _get_apps(request):
        url = 'apps/local?count=-1&output_mode=json'
        _, data = rest.simpleRequest(url, method='GET', sessionKey=request['session_key'])
        response = json.loads(data)

        apps = []

        for app in response['entry']:
            apps.append({'name': app['name'], 'label': app['content']['label']})

        return apps

    @staticmethod
    def _get_app_label_from_name(apps, app_name):
        for app in apps:
            if app['name'] == app_name:
                return app['label']
        return app_name
    
    @staticmethod
    def _escape_filename(file_name):
        return re.sub(r'[/\\?%*:|"<>]', '_', file_name)
    
    @staticmethod
    def _append_if_not_none(prefix, key, separator='.'):
        if prefix is not None and len(prefix) > 0:
            return prefix + separator + key
        
        return key
    
    def _flatten_dict(self, dict_source, output=None, prefix='', fields=None):
        if output is None:
            output = OrderedDict()

        for key in dict_source:
            value = dict_source[key]
            flattened_key = self._append_if_not_none(prefix, key)
            treat_as_text_blob = fields is not None and flattened_key in fields

            if treat_as_text_blob and (
                isinstance(value, dict)
                or isinstance(value, OrderedDict)
                or (isinstance(value, Sequence) and not isinstance(value, str))
            ):
                output[flattened_key] = json.dumps(value)
            elif isinstance(value, dict) or isinstance(value, OrderedDict):
                self._flatten_dict(value, output, flattened_key, fields=fields)
            else:
                output[flattened_key] = value

        return output

    # Endpoint helpers
    def handle(self, request_string):
        """
        Handles a request string by parsing it and executing the corresponding function.
        """
        try:
            args = self._parse_request_string(request_string)
            session_key = args['session']['authtoken']
            user = args['session']['user']
            method = args['method']

            if 'path_info' in args:
                path = args['path_info']
            else:
                return {'payload': 'No path was provided.', 'status': 403}

            if method.lower() == 'post':
                query = self._get_forms_args_as_dict(args['form'])
            else:
                query = args['query_parameters']

            request = {'user': user, 'session_key': session_key, 'method': method, 'path': path, 'query': query, 'args': args}

            function_name = self._get_function_signature(method, path)

            try:
                function_to_call = getattr(self, function_name)
            except AttributeError:
                function_to_call = None

            if function_to_call is not None:
                if self.logger is not None:
                    self.logger.info('Executing function, name=%s.', function_name)

                return function_to_call(request, **query)
            else:
                if self.logger is not None:
                    self.logger.warn('A request could not be executed since the associated function ' + 'is missing, name=%s.', function_name)

                return {'payload': 'Path was not found.', 'status': 404}
        except splunk.ResourceNotFound:
            self.logger.exception('Unable to find the lookup.')

            return self._render_error_json('Unable to find the lookup.', 404)
        except Exception as exception:
            if self.logger is not None:
                self.logger.exception('Failed to handle request due to an unhandled exception.')

            return {'payload': 'An unexpected error occurred while processing the request.', 'status': 500}
        
    @staticmethod
    def _is_filename_valid(lookup_file):
        allowed_path = re.compile(r'^[-A-Z0-9_ ]+([.][-A-Z0-9_ ]+)*$', re.IGNORECASE)
        
        return bool(allowed_path.match(lookup_file))
    
    @staticmethod
    def _is_lookup_in_users_path(lookup_file_path):
        return 'etc/users/' in lookup_file_path.replace('\\', '/')
    
    @staticmethod
    def _is_supported_lookup(lookup_name):
        if lookup_name.endswith('.default'):
            return False
        elif '.ds_store' in lookup_name.lower():
            return False
        elif lookup_name.endswith(f'.{LookupType.KMZ.value}') or \
            lookup_name.endswith(f'.{LookupType.KML.value}'):
            return False
        else:
            return True
        
    @staticmethod
    def _build_lookup_path(lookup_file, namespace=LookupConstants.DEFAULT_APP, owner=None):
        lookup_file = os.path.basename(lookup_file)
        namespace = os.path.basename(namespace)

        if owner is not None:
            owner = os.path.basename(owner)

        if owner is not None and owner != LookupConstants.OPTION_NOBODY and owner.strip() != '':
            return util.make_splunkhome_path(['etc', 'users', owner, namespace, 'lookups', lookup_file])

        else:
            return util.make_splunkhome_path(['etc', 'apps', namespace, 'lookups', lookup_file])
        
    def _get_backup_directory(
            self, session_key, lookup_file, namespace, owner=None, lookup_path=None
        ):
        namespace = os.path.basename(namespace)

        if owner is None:
            owner = LookupConstants.OPTION_NOBODY
        
        owner = os.path.basename(owner)

        if lookup_path is None:
            lookup_path = LookupTableFile.get(LookupTableFile.build_id(lookup_file, namespace, owner), sessionKey=session_key).path

        backup_directory = util.make_splunkhome_path([os.path.dirname(lookup_path), 'lookup_file_backups', namespace, owner, self._escape_filename(lookup_file)])

        if not os.path.exists(backup_directory):
            os.makedirs(backup_directory)

        return backup_directory
    
    def _get_lookup_file_path(self, lookup_file, namespace=LookupConstants.DEFAULT_APP, owner=None, get_default_csv=True, version=None, throw_not_found=True, session_key=None):
        lookup_file = os.path.basename(lookup_file)
        namespace = os.path.basename(namespace)

        if owner is not None:
            owner = os.path.basename(owner)
            
        if version is not None:
            version = os.path.basename(version)

        if owner is None:
            owner = LookupConstants.OPTION_NOBODY

        try:
            lookup_path = LookupTableFile.get(LookupTableFile.build_id(lookup_file, namespace, owner), sessionKey=session_key).path
        except splunk.ResourceNotFound:
            if throw_not_found:
                raise
            else:
                return None

        if version is not None and owner not in [None, LookupConstants.OPTION_NOBODY]:
            lookup_path = util.make_splunkhome_path([self._get_backup_directory(session_key, lookup_file, namespace, owner, lookup_path=lookup_path), version])
            lookup_path_default = util.make_splunkhome_path(['etc', 'users', owner, namespace, 'lookups', lookup_file + '.default'])
        elif version is not None:
            lookup_path = util.make_splunkhome_path([self._get_backup_directory(session_key, lookup_file, namespace, owner, lookup_path=lookup_path), version])
            lookup_path_default = util.make_splunkhome_path(['etc', 'apps', namespace, 'lookups', lookup_file + '.default'])
        elif owner not in [None, LookupConstants.OPTION_NOBODY]:
            lookup_path_default = util.make_splunkhome_path(['etc', 'users', owner, namespace, 'lookups', lookup_file + '.default'])
        else:
            lookup_path_default = util.make_splunkhome_path(['etc', 'apps', namespace, 'lookups', lookup_file + '.default'])

        self.logger.info('Resolved lookup file, path=%s.', lookup_path)

        if get_default_csv and not os.path.exists(lookup_path) and os.path.exists(lookup_path_default):
            return lookup_path_default
        else:
            return lookup_path
        
    @staticmethod
    def _get_temporary_lookup_file(prefix=None, basedir=None):
        if prefix is None:
            prefix = 'lookup_gen_' + time.strftime('%Y%m%d_%H%M%S') + '_'
        
        if basedir is None:
            basedir = util.make_splunkhome_path(['var', 'run', 'splunk', 'lookup_tmp'])

        if not os.path.isdir(basedir):
            os.mkdir(basedir)

        if os.path.isdir(basedir):
            return tempfile.NamedTemporaryFile(prefix=prefix, suffix='.txt', mode='w+', dir=basedir, encoding='utf-8', delete=False)
        else:
            return None
        
    def _get_kv_fields_from_transform(self, session_key, collection_name, namespace=LookupConstants.DEFAULT_APP, owner=None):
        response, content = rest.simpleRequest(f'/servicesNS/nobody/{namespace}/data/transforms/lookups', sessionKey=session_key, getargs={
                'output_mode': 'json',
                'search': f'collection={collection_name}'
            })

        if response.status < 200 or response.status > 300:
            return None

        transforms = json.loads(content, object_pairs_hook=OrderedDict)
        transform = None

        if len(transforms['entry']) == 0:
            return None
        else:
            transform = transforms['entry'][0]
    
        if transform is not None and 'content' in transform and 'fields_array' in transform['content']:
            return transform['content']['fields_array']
        else:
            return None
        
    def _get_csv_lookup(self,  session_key,  lookup_file,  namespace=LookupConstants.DEFAULT_APP,  owner=None, get_default_csv=True,  version=None,  throw_exception_if_too_big=False):
        self.logger.debug(f'Version: + {str(version)}.')

        file_path = self._get_lookup_file_path(lookup_file, namespace, owner, get_default_csv,version, session_key=session_key, throw_not_found=True)

        if throw_exception_if_too_big:
            try:
                file_size = os.path.getsize(file_path)

                self.logger.info(
                    'Size of lookup file determined, file_size=%s, path=%s.',
                    file_size, file_path
                )

                if file_size > LookupConstants.MAXIMUM_EDITABLE_SIZE:
                    raise LookupFileTooBigException(file_size)

            except os.error:
                self.logger.exception('Error determining size of lookup file.')

        self.logger.info('Loading lookup file from path=%s.', file_path)

        return io.open(file_path, 'r', encoding='utf-8', errors='replace')
    
    def _get_kv_lookup(self, session_key, lookup_file, namespace=LookupConstants.DEFAULT_APP, owner=None):
        if owner is None:
            owner = LookupConstants.OPTION_NOBODY

        lookup_contents = []

        response, content = rest.simpleRequest(f'/servicesNS/nobody/{namespace}/storage/collections/config/{lookup_file}', sessionKey=session_key, getargs={'output_mode': 'json'})

        if response.status == 403:
            raise PermissionDeniedException('You do not have permission to view this lookup.')

        header = json.loads(content, object_pairs_hook=OrderedDict)

        fields = ['_key']

        for field in header['entry'][0]['content']:
            if field.startswith('field.'):
                fields.append(field[6:])

        if len(fields) <= 1:
            fields = self._get_kv_fields_from_transform(session_key, lookup_file, namespace, owner)

            if fields is None:
                self.logger.info('Unable to get the fields list from lookup transforms.', fields)
                
                fields = ['_key']
            else:
                self.logger.info('Got fields list from the transform, fields=%r.', fields)

        lookup_contents.append(fields)

        response, content = rest.simpleRequest(f'/servicesNS/{owner}/{namespace}/storage/collections/data/{lookup_file}', sessionKey=session_key, getargs={'output_mode': 'json'})

        if response.status == 403:
            raise PermissionDeniedException('You do not have permission to view this lookup.')

        rows = json.loads(content, object_pairs_hook=OrderedDict)

        for row in rows:
            new_row = []
            flattened_row = self._flatten_dict(row, fields=fields)

            for field in fields:
                if field in flattened_row:
                    new_row.append(flattened_row[field])
                else:
                    new_row.append('')

            lookup_contents.append(new_row)

        return lookup_contents
    
    def _force_lookup_replication(self, app, filename, session_key, base_uri=None):
        endpoint = '/services/replication/configuration/lookup-update-notify'

        if base_uri:
            replication_uri = base_uri + endpoint
        else:
            replication_uri = endpoint

        payload = {'app': app, 'filename': os.path.basename(filename), 'user': LookupConstants.OPTION_NOBODY}

        response, content = rest.simpleRequest(replication_uri, method='POST', postargs=payload, sessionKey=session_key, raiseAllErrors=False)

        if response.status == 400:
            if 'No local ConfRepo registered' in content:
                self.logger.info('Lookup table replication not applicable for %s: clustering not enabled.', filename)

                return (True, response.status, content)
            elif 'Could not find lookup_table_file' in content:
                self.logger.error('Lookup table replication failed for %s: status_code="%s", content="%s".', filename, response.status, content)

                return (False, response.status, content)
            else:
                self.logger.error('Lookup table replication failed for %s: status_code="%s", content="%s".', filename, response.status, content)

                return (False, response.status, content)
        elif response.status != 200:
            return (False, response.status, content)

        self.logger.info('Lookup table replication forced for %s.', filename)

        return (True, response.status, content)
    
    @staticmethod
    def _create_lookup_table(filename, lookup_file, namespace, owner, key):
        lookup_tmp = util.make_splunkhome_path(['var', 'run', 'splunk', 'lookup_tmp'])
        destination_lookup_full_path = os.path.join(lookup_tmp, lookup_file)

        shutil.move(filename, destination_lookup_full_path)

        url = f'/servicesNS/{owner}/{namespace}/data/lookup-table-files'
        postargs = {'output_mode': 'json', 'eai:data': str(destination_lookup_full_path), 'name': lookup_file}

        rest.simpleRequest(url, postargs=postargs, sessionKey=key, raiseAllErrors=True)

    @staticmethod
    def _update_lookup_table(filename, lookup_file, namespace, owner, key):
        lookup_tmp = util.make_splunkhome_path(['var', 'run', 'splunk', 'lookup_tmp'])
        destination_lookup_full_path = os.path.join(lookup_tmp, lookup_file)

        shutil.move(filename, destination_lookup_full_path)

        url = f'/servicesNS/{owner}/{namespace}/data/lookup-table-files/{lookup_file}'
        postargs = {'output_mode': 'json', 'eai:data': str(destination_lookup_full_path)}

        rest.simpleRequest(url, postargs=postargs, sessionKey=key, raiseAllErrors=True)

    def _update_lookup_contents(self, contents=None, lookup_file=None, namespace=LookupConstants.DEFAULT_APP, owner=None, session_key=None, user=None, isNew=False):
        if owner is None:
            raise NoOwnerException('Owner must be provided when updating a lookup file.')

        if not self._is_filename_valid(lookup_file):
            raise LookupNameInvalidException('The lookup filename contains disallowed characters.')

        file_path = self._get_lookup_file_path(lookup_file, namespace, owner, session_key=session_key, throw_not_found=False)

        parsed_contents = json.loads(contents, object_pairs_hook=OrderedDict)
        temp_file_handle = self._get_temporary_lookup_file()
        temp_file_name = temp_file_handle.name
        destination_lookup_full_path = self._build_lookup_path(lookup_file, namespace, owner)

        self.logger.debug('destination_lookup_full_path=%s.', destination_lookup_full_path)

        destination_lookup_path_only, _ = os.path.split(destination_lookup_full_path)

        try:
            os.makedirs(destination_lookup_path_only, 0o700)
            os.chmod(destination_lookup_path_only, 0o700)
        except OSError:
            self.logger.debug('Destination path of lookup already existed, no need to create it; destination_lookup_path=%s.', destination_lookup_path_only)

        try:
            if temp_file_handle is not None and os.path.isfile(temp_file_name):
                csv_writer = csv.writer(temp_file_handle, lineterminator='\n')

                for row in parsed_contents:

                    if not self._is_empty(row):
                        row = [col.replace('\0', '') for col in row]
                        csv_writer.writerow(row)
        finally:
            if temp_file_handle is not None:
                temp_file_handle.close()

        if file_path is None:
            self.logger.debug('Creating a new lookup file, user=%s, namespace=%s, lookup_file=%s, path="%s".', owner, namespace, lookup_file, temp_file_name)
            
            self._create_lookup_table(filename=temp_file_name, lookup_file=lookup_file, namespace=namespace, owner=owner, key=session_key)

            self.logger.info('Lookup created successfully, user=%s, namespace=%s, lookup_file=%s, path="%s".', user, namespace, lookup_file, destination_lookup_full_path)
        else:
            if isNew=='true':
                raise LookupAlreadyExistsException('Lookup already exists.')
            else:
                if not self._is_lookup_in_users_path(file_path) or owner == LookupConstants.OPTION_NOBODY:
                    self._update_lookup_table(filename=temp_file_name, lookup_file=lookup_file, namespace=namespace, owner=LookupConstants.OPTION_NOBODY, key=session_key)
                else:
                    self._update_lookup_table(filename=temp_file_name, lookup_file=lookup_file, namespace=namespace, owner=owner, key=session_key)

                self.logger.info('Lookup edited successfully, user=%s, namespace=%s, lookup_file=%s.', user, namespace, lookup_file)

        try:
            self._force_lookup_replication(namespace, lookup_file, session_key)
        except splunk.ResourceNotFound:
            self.logger.info('Unable to force replication of the lookup file to other search heads; upgrade Splunk to 6.2 or later in order to support CSV file replication.')
        except splunk.AuthorizationFailed:
            self.logger.warning('Unable to force lookup file replication (not authorized), user=%s, namespace=%s, lookup_file=%s.', user, namespace, lookup_file)
        except Exception as exp:
            self.logger.exception('force lookup replication failed: user=%s, namespace=%s, lookup_file=%s, details=%s.', user, namespace, lookup_file, exp)

        return file_path
    
    def _get_backup_files(self, session_key, lookup_file, namespace, owner):
        escaped_filename = self._escape_filename(lookup_file)
        backup_directory = self._get_backup_directory(session_key, escaped_filename, namespace, owner)

        self.logger.info('Backup directory: %s.', backup_directory)

        backups = []

        for f in os.listdir(backup_directory):
            if os.path.isfile(os.path.join(backup_directory, f)):
                backups.append({'backup': f, 'size': os.path.getsize(os.path.join(backup_directory, f))})

        return backups
    
    def _get_lookup_backup_size(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
            
            backups = self._get_backup_files(request['session_key'], lookup_file, namespace, owner)
            total_backup_size = 0
            recent_backup= ''
            backup_count = len(backups)

            if backups and backup_count > 0:
                recent_backup = backups[0]['backup']

                for backup in backups:
                    try: 
                        if backup['size'] > 0:
                            total_backup_size += backup['size']
                    except ValueError:
                        self.logger.warning('Backup file name is invalid, file_name=%s.', backup)

            return [total_backup_size, recent_backup, backup_count]
    
    def _create_lookup_backup(self, session_key, lookup_file, namespace, resolved_file_path, owner=None, file_save_time=None):
        try:
            backup_directory = self._get_backup_directory(session_key, lookup_file, namespace, owner, resolved_file_path)

            try:
                file_time = os.path.getmtime(resolved_file_path)
            except:
                self.logger.warning('Unable to get the file modification time for the existing lookup file="%s".', resolved_file_path)

                file_time = None

            if file_save_time is not None:
                file_time = file_save_time
            
            if file_time is None:
                file_time = time.time()

            destination = util.make_splunkhome_path([backup_directory, str(file_time)])

            shutil.copyfile(resolved_file_path, destination)
            shutil.copystat(resolved_file_path, destination)

            self.logger.info('A backup of the lookup file was created, namespace=%s, lookup_file="%s", backup_file="%s".', namespace, lookup_file, destination)

            return destination
        except:
            self.logger.exception('Error when attempting to make a backup; the backup will not be made.')

            return None
        
    def _is_lookup_backup_deleted(self, session_key, lookup_file, namespace, owner=None):
        escaped_filename = self._escape_filename(lookup_file)
        backup_directory = self._get_backup_directory(session_key, escaped_filename, namespace, owner)

        if os.path.exists(backup_directory):
            shutil.rmtree(backup_directory)
            return True
        else:
            return False
        
    def _delete_lookup_backup(self, request, lookup_file=None, namespace=None, backup=None, owner=None, action='delete', **kwargs):
        if action == 'delete':
            try:
                if not lookup_file or not namespace or not owner or not backup:
                    self.logger.error('Missing required parameters: lookup_file=%s, namespace=%s, owner=%s, backup=%s.', lookup_file, namespace, owner, backup)

                    return {'payload': 'Missing required parameters.', 'status': 400,}

                escaped_filename = self._escape_filename(lookup_file)
                backup_directory = self._get_backup_directory(request['session_key'], escaped_filename, namespace, owner)

                if backup_directory and backup and '/' not in backup:
                    backup_file_path = os.path.join(backup_directory, os.path.basename(backup))

                    if os.path.exists(backup_file_path):
                        os.remove(backup_file_path)

                        self.logger.info('Deleted a backup of a lookup file, file_path=%s.', backup_file_path)

                        return {'payload': 'Deleted backup.', 'status': 200}
                    
                    self.logger.warning('Backup file not found: %s.', backup_file_path)

                    return {'payload': 'Backup not found.', 'status': 404}

                self.logger.warning('Invalid backup file or backup directory: %s, %s.', backup, backup_directory,)

                return {'payload': 'Invalid backup file or backup directory.', 'status': 400,}
            except splunk.ResourceNotFound:
                self.logger.error('Resource not found during backup deletion')

                return {'payload': 'Backup not found.','status': 404}
            except Exception as error:
                self.logger.exception('Error deleting backup: %s.', str(error))

                return {'payload': 'Backup not deleted: %s.' % str(error), 'status': 500}
        else:
            return self._delete_lookup_all_backups(request, lookup_file, namespace, owner)
        
    def _delete_lookup_all_backups(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
        try:
            deleted = self._is_lookup_backup_deleted(request['session_key'], lookup_file, namespace, owner)

            if deleted:
                self.logger.info('Deleted all backups for lookup file: %s, namespace: %s, owner: %s.', lookup_file, namespace, owner)

                return {'payload': 'Deleted all backups.', 'status': 200}

            self.logger.warning('No backups found to delete for lookup file: %s, namespace: %s, owner: %s.', lookup_file, namespace, owner)

            return {'payload': 'Backup not found.','status': 404}
        except Exception as error:
            self.logger.exception('Error deleting all backups: %s.', str(error))

            return {'payload': 'Error deleting all backups: %s.' % str(error),'status': 500}
        
    def _get_daily_backup_files(self, session_key, lookup_file, namespace, owner):
        escaped_filename = self._escape_filename(lookup_file)
        backup_directory = self._get_backup_directory(session_key, escaped_filename, namespace, owner)
        cutoff_time = datetime.datetime.now().timestamp() - 86400
        daily_backups = []

        self.logger.info('Backup directory: %s.', backup_directory)

        for backup_file in os.listdir(backup_directory):
            backup_file_path = os.path.join(backup_directory, backup_file)
            if not os.path.isfile(backup_file_path):
                continue

            try:
                if float(backup_file) >= cutoff_time:
                    daily_backups.append({'backup': backup_file, 'size': os.path.getsize(backup_file_path)})
            except ValueError:
                self.logger.warning('Backup file name is invalid, file_name=%s.', backup_file)

        return daily_backups
        
    def _get_daily_lookup_backup_size(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
        daily_backups = self._get_daily_backup_files(request['session_key'], lookup_file, namespace, owner)

        self.logger.info('Lookup name: %s', lookup_file)
        self.logger.info('Daily backups: %s', daily_backups)

        total_backup_size = 0
        backup_count = len(daily_backups)

        if daily_backups and backup_count > 0:
            for backup in daily_backups:
                try: 
                    if backup['size'] > 0:
                        total_backup_size += backup['size']
                except ValueError:
                    self.logger.warning('Backup file name is invalid, file_name=%s', backup)

        return total_backup_size
    
    def _build_lookup_backup_metadata(self, response, request, chunk_result):
        self.logger.info('Number of lookups metadata to process: %s.', len(response))

        try:
            for i in range(len(response)):
                lookup_name = response[i]['name']
                lookup_author = response[i]['author']
                lookup_app = response[i]['acl']['app']
                lookup_owner = response[i]['acl']['owner']
                canWrite = response[i]['acl']['can_write']
                sharing = response[i]['acl']['sharing']
                updated = response[i]['updated']
                url = response[i]['id']
                removable = response[i]['acl']['removable']

                if response[i]['acl']['sharing'] == 'global' or response[i]['acl']['sharing'] == 'app':
                    endpoint_owner = LookupConstants.OPTION_NOBODY
                else:
                    endpoint_owner = lookup_owner

                if self._is_supported_lookup(lookup_name=lookup_name):
                    backup_details = self._get_lookup_backup_size(
                        request=request, 
                        lookup_file=lookup_name, 
                        namespace=lookup_app, 
                        owner=endpoint_owner
                    )
                
                    backup_size = backup_details[0]
                    recent_backup = backup_details[1]
                    backup_count = backup_details[2]

                    chunk_result.append({
                        'name': lookup_name,
                        'author': lookup_author,
                        'owner': lookup_owner,
                        'app': lookup_app,
                        'endpoint_owner': endpoint_owner,
                        'backup_size': backup_size,
                        'backup_size_readable': self._format_size(backup_size),
                        'recent_backup': recent_backup,
                        'backup_count': backup_count,
                        'canWrite': canWrite,
                        'sharing': sharing,
                        'updated': updated,
                        'url': url,
                        'removable': removable
                    })     
        except Exception as e:
            self.logger.exception(e)

    # Endpoint functions
    def get_ping(self, request, **kwargs):
        """
        Return a response indicating that the REST handler is online.
        """

        return {'payload': 'Online', 'status': 200, 'headers': {'Content-Type': 'text/plain'}}

    def post_ping(self, request, **kwargs):
        """
        Return a response indicating that the REST handler is online.
        """

        return self.get_ping(request, **kwargs)

    def head_ping(self, request, **kwargs):
        """
        Return a response indicating that the REST handler is online.
        """

        return self.get_ping(request, **kwargs)
    
    def post_file_size(self, request, **kwargs):
        """
        Handles POST requests to get the file size of lookup files.
        """
        userEncoded = urllib.parse.quote(request['user'])
        url = f'/servicesNS/{userEncoded}/-/data/lookup-table-files?count=-1&output_mode=json'
        _, data = rest.simpleRequest(url, method='GET', sessionKey=request['session_key'])
        response = json.loads(data)

        csv_lookup_sizes = []
        apps = self._get_apps(request=request)

        if 'entry' in response:
            result_count = len(response['entry'])
            
            if result_count > 0:
                for i in range(result_count):
                    lookup_name = response['entry'][i]['name']

                    if not self._is_supported_lookup(lookup_name=lookup_name):
                        continue

                    lookup_author = response['entry'][i]['author']
                    lookup_app = response['entry'][i]['acl']['app']
                    lookup_owner = response['entry'][i]['acl']['owner']
                    lookup_data = response['entry'][i]['content']['eai:data']

                    try:
                        size = os.path.getsize(lookup_data)
                    except OSError as e:
                        if self.logger is not None:
                            self.logger.warning('Skipping unreadable lookup file %s at %s: %s.', lookup_name, lookup_data, str(e))

                        continue

                    date =  response['entry'][i]['updated']
                    can_write = response['entry'][i]['acl']['can_write']
                    lookup_sharing = response['entry'][i]['acl']['sharing']
                    lookup_id = response['entry'][i]['id']
                    removable = response['entry'][i]['acl']['removable']

                    self.logger.info('entry: %s', response['entry'][i])

                    if response['entry'][i]['acl']['sharing'] == 'global' or response['entry'][i]['acl']['sharing'] == 'app':
                        endpoint_owner = LookupConstants.OPTION_NOBODY
                    else:
                        endpoint_owner = lookup_owner

                    csv_lookup_sizes.append({
                        'name': lookup_name,
                        'author': lookup_author,
                        'app': self._get_app_label_from_name(apps=apps, app_name=lookup_app),
                        'can_write': can_write,
                        'owner': lookup_owner,
                        'sharing': lookup_sharing,
                        'lookup_id': lookup_id,
                        'removable': removable,
                        'namespace': lookup_app,
                        'endpoint_owner': endpoint_owner,
                        'info': lookup_data,
                        'size': size,
                        'size_readable': self._format_size(size),
                        'date': date
                    })

        return {'payload': csv_lookup_sizes, 'status': 200}
    
    def post_lookup_data(self, request, lookup_file=None, namespace=LookupConstants.DEFAULT_APP,owner=None, header_only=False, version=None, lookup_type=None, **kwargs):
        """
        Handles POST requests to retrieve the contents of a lookup file.
        """
        self.logger.info('Retrieving lookup content: namespace=%s, lookup=%s, type=%s, owner=%s, version=%s.', namespace, lookup_file, lookup_type, owner, version)

        if owner is None or (version and (not re.search(LookupConstants.NUMBER_VALIDATION_REGEX, version))):
            return self._render_error_json('You do not have permission to access this data.', 403)
    
        owner = os.path.basename(owner)

        if lookup_type is None or len(lookup_type) == 0:
            lookup_type = LookupType.CSV.value

            self.logger.warning('%s file does not have a type, it will default to CSV.', lookup_file)

        header_only = header_only in ['1', 'true', 1, True]

        try:
            if lookup_type == LookupType.CSV.value:
                with self._get_csv_lookup(request['session_key'], lookup_file,  namespace, owner,  version=version, throw_exception_if_too_big=True) as csv_file:
                    csv_reader = csv.reader([row.replace('\0','') for row in csv_file.readlines()])

                    lookup_contents = []

                    for row in csv_reader:
                        lookup_contents.append(row)

                        if header_only:
                            break

                    return self._render_json(lookup_contents)
            elif lookup_type == LookupType.KV.value:
                return self._render_json(self._get_kv_lookup(request['session_key'], lookup_file, namespace, owner))
            else:
                self.logger.warning(f'Lookup file type is not recognized, lookup_type={lookup_type}.')

                return self._render_error_json('Lookup file type is not recognized.', 421)
        except IOError:
            self.logger.warning('Unable to find the requested lookup.')

            return self._render_error_json('Unable to find the lookup.', 404)
        except (splunk.AuthorizationFailed, PermissionDeniedException) as e:
            self.logger.warning('Access to lookup denied.')

            return self._render_error_json('You do not have permission to perform this operation.', 403)
        except LookupFileTooBigException as e:
            self.logger.warning('Lookup file is too large to load. ')

            data = {'message': 'File too large: file size must be less than 10 MB to be edited.', 'file_size' : e.file_size}

            return {'payload': json.dumps(data), 'status': 420}
        except splunk.ResourceNotFound:
            self.logger.exception('Unable to find the lookup.')

            return self._render_error_json('Unable to find the lookup.', 404)
        except Exception as e:
            self.logger.exception('Lookup file could not be loaded.')

            return self._render_error_json(f'Lookup file could not be loaded: {e}.', 500)
        
    def post_lookup_contents(self, request, contents=None, lookup_file=None,namespace=LookupConstants.DEFAULT_APP, owner=None, backup=False, isNew=False, **kwargs):
        """
        Handles POST requests to update the contents of a lookup file, with optional backup creation.
        """
        try:
            if os.path.splitext(lookup_file)[1].lower() != f'.{LookupType.CSV.value}':
                return {'payload': 'Invalid file.', 'status': 403}
        
            if ':exsl' in contents:
                return {'payload': 'Invalid content.', 'status': 403}

            if backup == 'true':
                backup = True
                validate = self.post_check_backup_availability(request, lookup_file, namespace, owner)
                if validate['status'] != 200:
                    return validate
            else:
                backup = False

            if backup :
                data = {'lookup_file' : lookup_file, 'namespace' : namespace, 'owner' : owner, 'file_time' : time.time()}

                try:
                    _, _ = rest.simpleRequest('/services/data/lookup_edit/backup', sessionKey=request['session_key'], method='POST', postargs=data)
                except splunk.ResourceNotFound:
                    self.logger.info('Existing lookup could not be found for backup.')

            file_name = self._update_lookup_contents(contents, lookup_file, namespace, owner, request['session_key'], request['user'], isNew)

            return {'payload': str(file_name), 'status': 200}
        except (splunk.AuthorizationFailed, PermissionDeniedException):
            return self._render_error_json('You do not have permission to perform this operation.', 403)
        except LookupNameInvalidException:
            return self._render_error_json('Lookup name is invalid.', 400)
        except LookupAlreadyExistsException:
            return self._render_error_json('A CSV lookup with the same name already exists in this app. Please choose a different name or app.', 409)
        except NoOwnerException:
            return self._render_error_json('Owner must be provided when updating a lookup file.', 400)
        except Exception as e:
            self.logger.exception('Failed to save lookup: %s.', e)

            return self._render_error_json('Unable to save the lookup.')
        
    def post_kvlookup_contents(self, request, data=None, namespace=LookupConstants.DEFAULT_APP, owner=None, **kwargs):
        """
        Handles POST requests to update the contents of a KV store lookup file.
        """
        try:
            if not owner:
                owner = LookupConstants.OPTION_NOBODY

            postdata = {'name' : data}
            response, _ = rest.simpleRequest(f'/servicesNS/{owner}/{namespace}/storage/collections/config', sessionKey=request['session_key'], method='POST', postargs=postdata)

            self.logger.info('Saved KV lookup contents...%s',str(response))

            if response.status not in (200, 201):
                return self._render_error_json('Unable to save the lookup.', response.status)

            return {'payload': str(response), 'status': 200}
        except (splunk.AuthorizationFailed, PermissionDeniedException, splunk.ResourceNotFound):
            return self._render_error_json('You do not have permission to perform this operation.', 403)
        except LookupNameInvalidException:
            return self._render_error_json('Lookup name is invalid.', 400)
        except Exception as e:
            self.logger.exception('Failed to save lookup: details=%s.', e)

            return self._render_error_json('Unable to save the lookup.')
        
    def post_lookup_metadata(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
        """
        Handles POST requests to retrieve metadata for a given lookup file.
        """
        def timeout_handler(signum, frame):
            raise TimeoutError('Process is taking way too long.')

        alarm_enabled = (
            hasattr(signal, 'SIGALRM') and hasattr(signal, 'alarm')
            and threading.current_thread() is threading.main_thread()
        )
        previous_alarm_handler = None

        if alarm_enabled:
            previous_alarm_handler = signal.signal(signal.SIGALRM, timeout_handler)
            signal.alarm(900)
        
        try:
            if lookup_file is not None:
                try:
                    backup_details = self._get_lookup_backup_size(request=request, lookup_file=lookup_file, namespace=namespace, owner=owner)

                    if backup_details is not None:
                        backup_size, backup_count = backup_details[0], backup_details[2]

                        return {
                            'payload': {
                                'lookup_file': lookup_file,
                                'backup_count': backup_count,
                                'backup_size': backup_size,
                                'backup_size_readable': self._format_size(backup_size),
                            },
                            'status': 200
                        }
                    else:
                        return {
                            'payload': {
                                'lookup_file': lookup_file,
                                'backup_count': 0,
                                'backup_size_readable': '0 MB',
                            },
                            'status': 200
                        }
                except Exception as e:
                    self.logger.exception(e)

                    return {
                            'payload': {
                                'lookup_file': lookup_file,
                                'backup_count': 0,
                                'backup_size_readable': '0 MB',
                            },
                            'status': 404
                    }

            url = '/servicesNS/-/-/data/lookup-table-files?count=-1&output_mode=json'
            _, data = rest.simpleRequest(url, method='GET', sessionKey=request['session_key'])
            result = json.loads(data)

            lookup_results = []

            if 'entry' in result:
                result_count = len(result['entry'])

                if result_count > 0:
                    n_threads = 5

                    array_chunk = []

                    for i in range(0, n_threads):
                        array_chunk.append(result['entry'][i::n_threads])

                    thread_list = []
                    all_data = []

                    for _ in range(n_threads):
                        all_data.append([])

                    self.logger.info('---- Need data for ------ %s ---- Threads %s.', result_count, n_threads)

                    for thr in range(n_threads):
                        thread = threading.Thread(
                            target=self._build_lookup_backup_metadata, 
                            args=(array_chunk[thr], request, all_data[thr])
                        )
                        thread_list.append(thread)
                        thread_list[thr].start()

                    for thread in thread_list:
                        thread.join()

                    for result in all_data:
                        lookup_results.extend(result)

            return {'payload': lookup_results, 'status': 200}

        except TimeoutError as e:
            payload = {'message': 'Process timed out.'}

            self.logger.error(e)

            return {'payload': payload, 'status': 400}
        finally:
            if alarm_enabled:
                signal.alarm(0)
                signal.signal(signal.SIGALRM, previous_alarm_handler)
    
    def post_lookup_daily_data(self, request, **kwargs):
        """
        Handles command POST requests to retrieve daily backup data for lookup files.
        """
        _, data = rest.simpleRequest('/servicesNS/-/-/data/lookup-table-files?count=-1&output_mode=json', method='GET', sessionKey=request['session_key'])
        response = json.loads(data)
        lookup_list = []

        if 'entry' in response:
            for entry in response['entry']:
                lookup_name = entry['name']
                lookup_owner = entry['acl']['owner']
                lookup_app = entry['acl']['app']

                if entry['acl']['sharing'] in ['global', 'app']:
                    endpoint_owner = LookupConstants.OPTION_NOBODY
                else:
                    endpoint_owner = lookup_owner

                if self._is_supported_lookup(lookup_name=lookup_name):
                    daily_backup = self._get_daily_lookup_backup_size(request=request, lookup_file=lookup_name, namespace=lookup_app, owner=endpoint_owner)
                    
                    lookup_list.append({
                        'name': lookup_name,
                        'author': entry['author'],
                        'owner': lookup_owner,
                        'app': lookup_app,
                        'endpoint_owner': endpoint_owner,
                        'daily_backup': daily_backup,
                        'backup_size_readable': self._format_size(daily_backup)
                    })

        return {'payload': lookup_list, 'status': 200}
        
    def post_check_backup_availability(self, request, lookup_file=None, namespace=LookupConstants.DEFAULT_APP, owner=None, **kwargs):
        """
        Handles POST requests to check the availability of backup space.
        """
        splunk_home = os.getenv('SPLUNK_HOME')

        if not splunk_home:
            splunk_home = '/'

        total, used, free = shutil.disk_usage(splunk_home)

        self.logger.info('Disk space total: %s, used: %s, Free: %s.', total, used, free)

        if ((free / total) * 100) <= 10:
            return self._render_error_json('Unable to create backup. Available disk space is at 10%.', 507)

        try:
            lookup_info = self._get_kv_lookup(request['session_key'], LookupType.BACKUP_FILE.value)
        except (PermissionDeniedException, splunk.ResourceNotFound):
            self.logger.info('Backup limits lookup is unavailable, lookup_file=%s, namespace=%s.', lookup_file, namespace)

            lookup_info = []

        for row in lookup_info:
            if len(row) < 5:
                continue

            if row[4] == lookup_file and row[1] == namespace:
                if row[3] is not None and row[2] is not None and row[2] > row[3]:
                    return self._render_error_json(f'Unable to create backup. You have reached the backup size limit of {self._format_size(row[3], 0)}. You can edit backup limit to create more backups.', 500)
                
        return {'payload': 'Backup space available.', 'status': 200}
    
    def post_lookup_backups(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
        """
        Handles POST requests to retrieve the list of backup files for a given lookup file, along with their sizes and timestamps.
        """
        try:
            backups = self._get_backup_files(request['session_key'], lookup_file, namespace, owner)
            backups_meta = []

            for backup in backups:
                try:
                    if backup['size'] > 0:
                        backups_meta.append(
                            {
                                'time': backup['backup'],
                                'time_readable' : datetime.datetime.fromtimestamp(float(backup['backup'])).strftime('%Y-%m-%d %H:%M:%S'),
                                'size': backup['size'],
                                'size_readable': self._format_size(backup['size'], 2)
                            }
                        )
                except ValueError:
                    self.logger.warning('Backup file name is invalid, file_name=%s.', backup)

            backups_meta = sorted(backups_meta, key=lambda x: float(x['time']), reverse=True)

            return self._render_json(backups_meta)
        except (splunk.AuthorizationFailed, PermissionDeniedException) as e:
            self.logger.warning('Access to lookup denied.')

            return self._render_error_json('You do not have permission to perform this operation.', 403)
        except splunk.ResourceNotFound:
            self.logger.exception('Unable to find the lookup.')

            return self._render_error_json('Unable to find the lookup.', 404)
        except:
            self.logger.exception('Lookup file could not be loaded.')

            return self._render_error_json('Lookup file could not be loaded.', 500)

    def post_backup(self, request, lookup_file=None, namespace=LookupConstants.DEFAULT_APP,owner=None, file_time=None,action=None, backup=None,**kwargs):
        """
        Handles POST requests to create a backup of a lookup file or delete an existing backup, based on the specified action.
        """
        if action is None:
            if owner is None:
                return self._render_error_json('Unauthorized.', 403)

            valid_user = False

            response, content = rest.simpleRequest('/services/admin/users?output_mode=json', sessionKey=request['session_key'], method='GET')

            if response.status == 200:
                result = json.loads(content)

                if owner.lower() == LookupConstants.OPTION_NOBODY:
                    valid_user = True

                for entry in result['entry']:
                    if owner.lower() == entry['name'].lower():
                        valid_user = True

                        break
            else:
                self.logger.info('Unauthorized operation')

                return self._render_error_json('Unauthorized operation.', 403)

            if not valid_user:
                return self._render_error_json('Unauthorized operation.', 403)

            if not (file_time and re.search(LookupConstants.NUMBER_VALIDATION_REGEX, file_time)):
                file_time = None

            try:
                resolved_file_path = self._get_lookup_file_path(lookup_file, namespace, owner, session_key=request['session_key'], throw_not_found=True)
                file_path = self._create_lookup_backup(request['session_key'], lookup_file, namespace, resolved_file_path, owner, file_time)

                if file_path is None:
                    return self._render_error_json('Unable to create a backup of the lookup file.')

                self.logger.info('Created a backup of a lookup file, file_path=%s.', file_path)

                return {'payload': str(file_path), 'status': 200}
            except splunk.ResourceNotFound:
                self.logger.warning('Unable to find the lookup to backup.')

                return self._render_error_json('Unable to find the lookup to backup.', 404)
            except Exception as error:
                self.logger.exception('Exception generated when attempting to backup a lookup file: %s.', error)

                return self._render_error_json('Unable to backup the lookup %s.' % str(error))
        else:
            self.logger.info('Action is delete, proceeding to delete backup file, backup=%s.', backup)

            return self._delete_lookup_backup(request, lookup_file, namespace, backup, owner, action)

    def post_remove_lookup_backup(self, request, lookup_file=None, namespace=None, backup=None, owner=None, **kwargs):
        """
        Handles POST requests to delete a specific backup of a lookup file.
        """
        data = {'lookup_file': lookup_file, 'namespace': namespace, 'owner': owner, 'action': 'delete', 'backup': backup}

        try:
            response, payload = rest.simpleRequest( '/services/data/lookup_edit/backup', sessionKey=request['session_key'], method='POST',  postargs=data)

            if isinstance(payload, bytes):
                payload = payload.decode('utf8')

            return {'payload': payload, 'status': response.status}
        except splunk.ResourceNotFound:
            self.logger.info('Existing lookup could not be found for backup.')

    def post_remove_all_lookup_backups(self, request, lookup_file=None, namespace=None, owner=None, **kwargs):
        """
        Handles POST requests to delete all backups of a lookup file.
        """
        data = {'lookup_file': lookup_file, 'namespace': namespace, 'owner': owner, 'action': 'deleteAll', 'backup': None,}

        try:
            response, payload = rest.simpleRequest('/services/data/lookup_edit/backup', sessionKey=request['session_key'], method='POST', postargs=data)

            if isinstance(payload, bytes):
                payload = payload.decode('utf8')

            return {'payload': payload, 'status': response.status}
        except splunk.ResourceNotFound:
            self.logger.info('Existing lookup could not be found for backup.')

    def post_lookup_as_file(self, request, lookup_file=None, namespace=LookupConstants.DEFAULT_APP,owner=None, lookup_type=LookupType.CSV.value, **kwargs):
        """
        Handles POST requests to export a lookup file as a downloadable file, with support for different lookup types.
        """
        self.logger.info('Exporting lookup, namespace=%s, lookup=%s, type=%s, owner=%s.', namespace, lookup_file, lookup_type, owner)

        if lookup_type is None or len(lookup_type) == 0:
            lookup_type = LookupType.CSV.value

            self.logger.warning('%s file does not have a type, it will default to CSV.', lookup_file)

        try:
            if lookup_type == LookupType.CSV.value:
                with self._get_csv_lookup(request['session_key'], lookup_file, namespace, owner) as csv_file_handle:
                    csv_data = csv_file_handle.read()
            elif lookup_type == LookupType.KV.value:
                rows = self._get_kv_lookup(request['session_key'], lookup_file, namespace, owner)
                csv_data = self._convert_array_to_csv(rows)
            else:
                self.logger.warning(f'Lookup file type is not recognized, lookup_type={lookup_type}.')

                return self._render_error_json('Lookup file type is not recognized.', 421)

            filename = self._escape_filename(lookup_file)

            return {
                'payload': csv_data,
                'status': 200,
                'headers': {'Content-Type': 'text/csv', 'Content-Disposition': f'attachment; filename="{filename}"'},
            }
        except (IOError, splunk.ResourceNotFound):
            return self._render_error_json('Unable to find the lookup.', 404)
        except (splunk.AuthorizationFailed, PermissionDeniedException):
            return self._render_error_json('You do not have permission to perform this operation.', 403)
        except Exception as e:
            self.logger.exception('Export lookup: details=%s.', e)

            return self._render_error_json('Something went wrong!')

